            "swapping_pxa_to_pxs_is_instant_the": "PXA から PXS への変換は即時です。PXA の半分がすぐに変換され、5% の手数料が差し引かれます。残りの半分は担保としてロックされ、約3.5日後にその時点の価格に応じて調整されて返却されます。PXS から PXA への変換は手数料無料で、約3.5日後にその時点の witness の中央値価格で確定します。",
            "pxp_usable_because": "{{text}}：利用可能な PXP は <0>{{overall}}</0>（<1>{{borrowed}}</1> を借入、<2>{{lended}}</2> を貸出しているため）",
            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> は、通常の13週間のパワーダウンを経ずに、Pixa Power を別のアカウントへ直接送付できます。このトレジャリーはマルチシグのアカウントであるため、単独のログインで資金を動かすことはできません — 下の<strong>一括送付</strong>を使ってください。各鍵保有者が同じバッチに個別に署名し、それらを結合してからブロードキャストします。",
            "the_big_mac_index_is_a_renown": "ビッグマック指数は、購買力・インフレ・消費者物価を追跡する著名な経済指標です。",
            "beware_of_spam_and_phishing_links_in": "送金メモに含まれるスパムやフィッシングのリンクにご注意ください。信頼できない相手からのリンクは開かないでください。秘密鍵を第三者のサイトに入力しないでください。取引はブロックチェーン上で確認されるまで表示されず、数分かかることがあります。",
