            "are_you_sure_you_want_to_swap": "{{amount}} PXA を PXS に変換しますか？半分がすぐに変換され（5% の手数料を差し引き）、PXS は即時に付与されます。残りの半分は担保としてロックされ、約3.5日後にその時点の PXA 価格に応じて調整されて返却されます。価格が半分になっていた場合は、何も返却されません。変換は取り消せません。",
