            "pxp_is_pxa_0_frozen_solid_0": "PXP は<0>固く凝固した</0> PXA です——一対一でステークし、身体に重みと声を与えます。<1>融かせ</1>ば、十三週の解放をかけて液体の PXA に戻ります。同じ物質、二つの相。あわせて<2>アトラス</2>です。",
            "staking_is_not_idle_it_buys_four": "ステークは遊ばせておくことではありません。四つのものを買い——そのうちひとつが、静かに精神の向きを定めます。",
            "unstaking_is_gradual_and_fixed_power_down": "ステーク解除は段階的で、あらかじめ定まっています。パワーダウンすれば、あなたの PXP は<0> 十三回の等額の週次トランシェ</0>で液体の PXA に戻ります——およそ九十一日です。速さはプロトコルが定め、誰も速めることも遅らせることもできません。",
            "each_week_another_equal_slice_melts_back": "毎週、もう一枚の等しい薄片が液体の PXA に戻り、残高は 100 % に向かって一定で見通しのきく上り坂で使えるようになります。計画を示す図で、実データではありません。",
            "pxp_is_a_nutzungs_token_a_utility": "PXP は、2025年3月27日付 FINMA の判断（参照 G01518211）における Nutzungs-Token——ユーティリティトークンです。",
            "it_confers_protocol_functionality_governance_and": "これはプロトコルの機能——ガバナンスと手数料のかからない帯域——を与えるもので、Pixagram SA の収益や資産に対する請求権ではありません。ガバナンスへの参加は投資ではありません。プロトコルの運用を助けるためのステークは集団投資スキームではありません。決定的な点として、PXP を保有しても<0>利息は付きません</0>——リターンは投稿・投票・キュレーションといった能動的な参加からのみ生じ、受動的な利回りからは決して生じません。支払手段でも預金でもなく、返済義務を負う発行者は存在せず、CISA は適用されません。"
