            "when_you_settle_the_body_is_delivered": "決済のとき、身体は執行の瞬間に PXA として引き渡されます — オラクルが含意する重さにヘアカットを掛けた額です。だからこそ「原資産」という語は当たりません。原資産という語は、ものとその派生という二つの別々の資産を前提とするからです。しかし supra と atlas は二つのものではありません。ひとつの身体が二つの register で見られているのです — 身体はあるがままであり、supra はその身体が投影すべきだと精神が言うものです。意識は身体が所有する何かではありません。それは目覚めた身体そのものです。",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "リスクを取り除く貨幣の仕組みは存在しません。法定通貨準備型コインは、リスクをその準備の健全性と発行体の支払能力に集中させます。supra はそのリスクを創造経済のボラティリティ — アトラスの分散 — と合意の健全性 — witness のコンパスの確かさ — へ移し、守られた数字の陰に隠すのではなく、超過担保と何も守らないヘアカットによって公然と扱います。",
