            "adding_a_password_provides_extra_security_especi": "パスワードを設定すると、特に短いシードフレーズの場合に安全性が高まります。",
            "you_are_about_to_request_a_change": "<0>@{{username}}</0> の復旧アカウント変更を申請しようとしています。",
            "nominate_a_trusted_account_a_co_founder": "信頼できるアカウント——共同創業者、自分で管理する別のウォレット、あるいは別の手段で連絡が取れる相手——を指定しておくと、owner 鍵を紛失したり侵害されたりした場合にアクセスの回復を助けてもらえます。復旧の手続きは owner 鍵の履歴を用いるため、復旧アカウント単独であなたのアカウントを奪うことは決してできません。あくまで回復を手助けできるだけです。変更は30日間の保留期間を経て有効になります。",
            "strong_30_day_waiting_period_strong_changing": "<strong>30日間の待機期間。</strong> 復旧アカウントの変更は即時ではありません。新しい申請は<strong>ブロードキャストから30日後</strong>に有効となり、それまでは現在の復旧アカウントが有効です。待機期間中に再度ブロードキャストすると、保留中の申請が置き換わります。現在の値に戻すと、保留中の変更は取り消されます。",
            "pick_someone_you_trust_personally_a_co": "個人的に信頼できる相手を選んでください。共同創業者、自分で管理する別アカウント、または所有者に別の手段で連絡が取れるウォレットなどです。",
            "generate_a_fresh_seed_phrase_to_derive": "新しいシードフレーズを生成して、アカウントの新しい鍵を導出します。シードフレーズはすべてのアカウント鍵のマスターキーです——安全に保管し、決して共有しないでください。下で確認すると、鍵更新トランザクションの署名に owner 鍵が使われます。",
            "this_will_strong_cancel_any_pending_recovery": "これは現在の復旧アカウントと同じ値を再ブロードキャストすることで、<strong>保留中の復旧アカウント変更をすべて取り消します</strong>。30日間の申請は置き換えられ、その間ずっと現在の復旧アカウントが有効なままです。",
            "once_broadcast_the_chain_will_create_a": "ブロードキャストすると、チェーンは<strong>30日後</strong>に有効となる保留中の申請を作成します。それまでは現在の復旧アカウント（<0>@{{currentRecovery}}</0>）が有効です。<strong>owner 鍵</strong>の入力を求められます。",
            "posting_description_1": "このキーは、投稿・コメント・投票などのソーシャル操作に使用します。権限が限定されており、金銭に関わる操作には使用できません。",
            "posting_description_2": "このキーは、Pixagram.com など Pixa ベースの SNS へのログインに使用します。安全に保管してください。",
            "active_description_1": "このキーには、トークンの送金や交換など、より機微な金銭関連の操作を行う追加の権限があります。",
            "active_description_2": "ウォレット関連の操作では、Active キーによる認証を求められることがあります。Active Key は信頼できるアプリにのみ入力してください。このキーを入手した人は誰でもあなたのトークンを奪えます。",
            "owner_description_1": "Owner キーは他のキーを変更するために必要です。アカウントの復旧や他のキーの変更を行う追加の権限を持ちます。最も重要なキーであり、オフラインで安全に保管してください。",
