            "in_short": "概要",
            "courtesy_summary_not_binding": "（便宜上の要約であり、法的拘束力はありません）。",
            "most_of_pixagram_is_public_by_design": "Pixagram の大部分は、設計上公開されています。本プロトコルを通じてあなたが公開するものは、誰でも閲覧でき、誰も管理していない当事者によって複製され、恒久的に残ります — 運営者はそれを監視することも、編集することも、消去することもできません。本ポリシーが対象とする非公開の部分は、意図的に小さく抑えています。アカウント作成時の1回限りの電話番号確認、本インターフェースの運用と保護のための一時的な技術データ、そして法律により当社が保管を義務付けられている記録です。当社は広告を配信せず、プロファイルを作成せず、あなたに関するいかなる情報も販売しません。",
            "this_privacy_policy_uses_the_defined_terms": "本プライバシーポリシーでは、利用規約で定義された用語（「本インターフェース」「本プロトコル」「コンテンツ」「永続ストレージ」「プロキシ」「アカウント」「登録簿」を含みます）を使用しており、利用規約と併せてお読みいただく必要があります。",
            "1_who_we_are_and_how_to": "1. 当社について、および当社への連絡方法",
            "pixa_rex_s_a_a_sociedad_anonima": "Pixa Rex S.A.（パナマ共和国の法律に基づく sociedad anónima であり、パナマ公共登記所に Mercantile Folio No. 155788210 として登記され、所在地を Advanced Tower Building, First Floor, Ricardo Arias Street, Panama City, Republic of Panama とする法人。以下「運営者」または「当社」といいます）は、本ポリシーに記載するオフチェーンの個人データの管理者です。プライバシーに関するお問い合わせ先は contact@pixarex.net です。",
            "2_the_two_layers_of_pixagram": "2. Pixagram の2つの層",
            "the_public_layer_accounts_posts_pixel_art": "公開層。本プロトコルおよび永続ストレージに記録されたアカウント、投稿、ピクセルアート、投票、メタデータおよびメディアは、公開され、誰でも閲覧でき、恒久的に残ります。誰も — あなたも運営者も — それらを消去または改変することはできず、独立した当事者が誰の手も届かないところでそれらを複製します。運営者は本インターフェースを通じてその公開状態を表示しますが、それを保管してはいません。公開する内容はこの点を踏まえて選び、いつか消したくなるかもしれない個人情報は決して公開しないでください。公開は取り消すことができません。",
            "the_off_chain_layer_the_small_set": "オフチェーン層。運営者自身が処理する少数のデータで、第3項に列挙しています。この層には、あなたのデータ保護に関する権利が全面的に適用されます。",
            "3_what_we_process_off_chain_and": "3. 当社がオフチェーンで処理するデータとその理由",
            "account_creation_phone_check": "アカウント作成 — 電話番号確認。",
            "to_keep_account_creation_human_and_roughly": "アカウント作成を人間によるものに保ち、おおむね1人1アカウントとするため、あなたの電話番号は当社が利用する事業者である Bird（旧 MessageBird）を通じて1回だけ確認されます。確認コードを送信するため、あなたの番号は通常の手続きとして Bird に送信され、Bird の規約に基づいて処理されます。Bird は確認済み番号について独自の記録を保持していますが、運営者はそれをあなたのアカウントと結び付けることはできません。運営者自身が保持するのは番号の一方向ハッシュのみであり、すでに使用された番号を識別するためだけに使用します。電話番号のハッシュは匿名ではなく、個人データであることに変わりはありませんが、当社に番号そのものを明かすことはなく、重複アカウントと不正利用の防止以外の目的には使用されず、共有されることもありません。根拠：正当な利益（不正利用および重複アカウントの防止）。",
            "age_assurance_only_where_applied": "年齢確認（実施する場合のみ）。",
            "we_do_not_generally_require_identity_or": "当社は原則として、本人確認や書類による年齢確認を求めません。適用法により年齢確認が義務付けられている場合、または特定のコンテンツ、機能もしくは法域について合理的に必要な場合（利用規約第2条）には、いかなる確認もデータ最小化を図るよう設計されます — たとえば、画像や書類を保持せずに行う年齢推定です。根拠：契機に応じて、法的義務および／または正当な利益。",
