            "5_minimum_age": "5. 最低年齢",
            "the_interface_is_intended_for_users_aged": "本インターフェースは、16歳以上の利用者、またはあなたに適用される法律がそれより高い最低年齢を定めている場合はその年齢以上の利用者を対象としています。本インターフェースは16歳未満の子どもを対象としておらず、当社は16歳未満の子どもの個人データを故意に処理することはありません。16歳未満の子どもが当社に個人データを提供したと思われる場合は、contact@pixarex.net までご連絡ください。当社が対処します。18歳未満の場合、一部のコンテンツやデジタル資産の機能を利用できないか、制限されることがあります（利用規約第2条）。データ最小化はあらゆる場面で適用され、永続性に関する警告は若い利用者にとって特に重要です。個人情報は決して公開しないでください — 誰にも元に戻すことはできません。",
