            "fr_operations_note": "臨時的な投資家の場合、受け取った報酬は原則として受取時には課税されません — 取得価額ゼロでポートフォリオに組み入れられ、最終的にユーロへ換金する際に（プラットフォーム外で、ポートフォリオの譲渡計算式により）その全額が課税されます。以下の行は受け取ったものの記録であり、ここでは一切所得として計上していません。活動が継続的／職業的である場合は、代わりに受取時に BNC として扱われます — 専門家にご確認ください。",
            "fr_assumption_note": "暗号資産同士の課税繰延べは、PXS が電子マネーではなくデジタル資産（actif numérique）に該当することを前提としています。PXS が法定通貨を参照する電子マネーとして再分類された場合、PXA→PXS の変換が課税対象の譲渡となる可能性があります — これは未解決の性質決定の問題です。",
